import React, { useMemo, useState } from 'react';

const COLUMN_NAMES = {
  year: 'Năm',
  quarter: 'Quý',
  month: 'Tháng',
  customer_type: 'Loại Khách',
  product_key: 'Sản Phẩm',
  store_key: 'Cửa Hàng',
  city: 'Thành Phố',
  total_quantity: 'Tổng SL',
  sum_amount: 'Tổng Tiền',
  quantity_on_hand: 'Tồn Kho',
  average_price: 'Giá TB',
  turnover_ratio_percent: 'Tỷ Lệ Quay Hàng (%)',
  sales_qty: 'SL Bán',
  inventory_qty: 'SL Tồn',
};

export const DataTable = ({ data = [], columns = [], onDrillThrough = null }) => {
  const [sortBy, setSortBy] = useState(null);
  const [sortOrder, setSortOrder] = useState('asc');

  const tableColumns = columns.length > 0 ? columns : (data.length > 0 ? Object.keys(data[0]) : []);

  const sortedData = useMemo(() => {
    if (!sortBy || data.length === 0) return data;

    const sorted = [...data].sort((a, b) => {
      const aVal = a[sortBy];
      const bVal = b[sortBy];

      if (typeof aVal === 'number' && typeof bVal === 'number') {
        return sortOrder === 'asc' ? aVal - bVal : bVal - aVal;
      }

      const aStr = String(aVal).toLowerCase();
      const bStr = String(bVal).toLowerCase();
      return sortOrder === 'asc' ? aStr.localeCompare(bStr) : bStr.localeCompare(aStr);
    });

    return sorted;
  }, [data, sortBy, sortOrder]);

  const handleSort = (col) => {
    if (sortBy === col) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortBy(col);
      setSortOrder('asc');
    }
  };

  const formatValue = (val) => {
    if (!val && val !== 0) return '—';
    if (typeof val === 'number') {
      if (val >= 1e9) return (val / 1e9).toFixed(2) + 'T';
      if (val >= 1e6) return (val / 1e6).toFixed(2) + 'M';
      if (val >= 1e3) return (val / 1e3).toFixed(2) + 'K';
      return val.toFixed(0);
    }
    return val;
  };

  const getColumnLabel = (col) => COLUMN_NAMES[col] || col;

  return (
    <div style={{ overflowX: 'auto', marginBottom: '20px' }}>
      <table
        style={{
          width: '100%',
          borderCollapse: 'collapse',
          backgroundColor: 'white',
          borderRadius: '6px',
          overflow: 'hidden',
        }}
      >
        <thead>
          <tr style={{ backgroundColor: '#667eea', color: 'white' }}>
            {tableColumns.map((col) => (
              <th
                key={col}
                onClick={() => handleSort(col)}
                style={{
                  padding: '12px',
                  textAlign: 'left',
                  cursor: 'pointer',
                  fontWeight: '600',
                  borderBottom: '2px solid #667eea',
                  userSelect: 'none',
                }}
              >
                {col.replace(/_/g, ' ')} {sortBy === col && (sortOrder === 'asc' ? '↑' : '↓')}
              </th>
            ))}
            {onDrillThrough && <th style={{ padding: '12px', textAlign: 'center' }}>Action</th>}
          </tr>
        </thead>
        <tbody>
          {sortedData.map((row, idx) => (
            <tr
              key={idx}
              style={{
                backgroundColor: idx % 2 === 0 ? '#f9f9f9' : '#fff',
                borderBottom: '1px solid #eee',
                ':hover': { backgroundColor: '#f0f0f0' },
              }}
            >
              {tableColumns.map((col) => (
                <td key={col} style={{ padding: '12px', textAlign: 'left' }}>
                  {formatValue(row[col])}
                </td>
              ))}
              {onDrillThrough && (
                <td style={{ padding: '12px', textAlign: 'center' }}>
                  <button
                    onClick={() => onDrillThrough(row)}
                    style={{
                      padding: '6px 12px',
                      backgroundColor: '#764ba2',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      fontSize: '0.85em',
                    }}
                  >
                    Drill Through
                  </button>
                </td>
              )}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default DataTable;
